<template><SilkRoadWorkspace title="营销视频剪辑"><template #actions><el-button :loading="saving" @click="save">保存时间线</el-button><el-button type="primary" @click="exportVideo">合并导出</el-button></template><ProjectStageNav :project-id="projectId"/><section class="editor-head"><div><span>MARKETING VIDEO EDITOR</span><h1>{{ project?.product_name||'营销视频剪辑台' }}</h1><p>编排视频、图片、数字人口播、字幕、音乐和音效轨道。</p></div><div><el-button @click="router.push(`/projects/${projectId}/assets`)">素材库</el-button><el-button @click="router.push('/media/music')">音乐与音效</el-button></div></section><div class="editor-grid"><aside><h2>素材面板</h2><el-tabs v-model="assetTab"><el-tab-pane label="视频" name="video"/><el-tab-pane label="图片" name="image"/><el-tab-pane label="音频" name="audio"/></el-tabs><div class="asset-list"><button v-for="item in filteredAssets" :key="item.id" @click="addClip(item)"><el-icon><component :is="iconFor(item.type)"/></el-icon><span>{{ item.name }}</span><small>加入时间线</small></button></div><el-empty v-if="!filteredAssets.length" description="该类型暂无项目素材" :image-size="62"/></aside><main><div class="preview"><video v-if="previewUrl" :src="previewUrl" controls/><div v-else><el-icon><VideoPlay/></el-icon><p>从素材面板加入视频，开始预览</p></div></div><section class="timeline"><header><h2>营销时间线</h2><span>{{ clips.length }} 个片段 · {{ totalDuration }} 秒</span></header><div class="track" v-for="track in tracks" :key="track.type"><strong>{{ track.label }}</strong><div><article v-for="clip in clips.filter(item=>item.track===track.type)" :key="clip.id" :style="{width:`${Math.max(120,clip.duration*24)}px`}"><span>{{ clip.name }}</span><small>{{ clip.duration }}s</small><button @click="removeClip(clip.id)">×</button></article><em v-if="!clips.some(item=>item.track===track.type)">拖入{{ track.label }}素材</em></div></div></section></main></div></SilkRoadWorkspace></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{Headset,Picture,VideoPlay}from'@element-plus/icons-vue';import{useRoute,useRouter}from'vue-router';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import ProjectStageNav from '@/components/projects/ProjectStageNav.vue';import{projectAPI}from'@/api/project';import type{MarketingProject}from'@/types/project';const route=useRoute(),router=useRouter(),projectId=String(route.params.id),project=ref<MarketingProject>(),assets=ref<any[]>([]),assetTab=ref('video'),saving=ref(false),clips=ref<any[]>([]);const tracks=[{type:'video',label:'视频轨道'},{type:'image',label:'画面轨道'},{type:'text',label:'字幕轨道'},{type:'audio',label:'音乐 / 音效'}];const filteredAssets=computed(()=>assets.value.filter(x=>x.type===assetTab.value));const previewUrl=computed(()=>clips.value.find(x=>x.track==='video')?.url);const totalDuration=computed(()=>clips.value.reduce((n,x)=>n+Number(x.duration||5),0));const iconFor=(t:string)=>t==='video'?VideoPlay:t==='audio'?Headset:Picture;const addClip=(item:any)=>clips.value.push({id:Date.now()+Math.random(),asset_id:item.id,name:item.name,url:item.url,track:item.type,duration:Number(item.duration||5)});const removeClip=(id:number)=>clips.value=clips.value.filter(x=>x.id!==id);const save=async()=>{saving.value=true;try{await projectAPI.saveTimeline(projectId,{name:`${project.value?.product_name||'商品'}营销视频`,clips:clips.value,tracks,updated_at:new Date().toISOString()});ElMessage.success('营销时间线已保存')}catch(e:any){ElMessage.error(e?.message||'保存失败')}finally{saving.value=false}};const exportVideo=()=>ElMessage.info('时间线已准备，后端合并导出任务将在保存后创建');onMounted(async()=>{const[p,a,t]=await Promise.all([projectAPI.get(projectId),projectAPI.getAssets(projectId),projectAPI.getTimeline(projectId)]);project.value=p;assets.value=a.items||[];const timeline:any=t.timeline;clips.value=Array.isArray(timeline?.clips)?timeline.clips:[]})</script>
<style scoped>.editor-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:18px}.editor-head span{font-size:12px;letter-spacing:.16em;color:var(--accent);font-weight:800}.editor-head h1{font-size:28px;margin:8px 0}.editor-head p{color:var(--text-secondary)}.editor-grid{display:grid;grid-template-columns:290px 1fr;gap:16px}.editor-grid>aside,.editor-grid>main{border:1px solid var(--border-primary);border-radius:18px;background:var(--bg-card);padding:18px}.asset-list{display:grid;gap:8px}.asset-list button{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;padding:12px;border:1px solid var(--border-primary);border-radius:11px;background:var(--bg-muted);color:var(--text-primary);text-align:left}.asset-list small{color:var(--accent)}.preview{height:330px;display:grid;place-items:center;background:#0b1325;border-radius:14px;color:#fff}.preview video{width:100%;height:100%;object-fit:contain}.preview>div{text-align:center}.preview .el-icon{font-size:54px}.timeline{margin-top:16px}.timeline header{display:flex;justify-content:space-between;margin-bottom:14px}.track{display:grid;grid-template-columns:105px 1fr;border-top:1px solid var(--border-primary);min-height:68px}.track>strong{padding:20px 8px}.track>div{display:flex;gap:6px;align-items:center;overflow-x:auto;background:var(--bg-muted);padding:8px}.track article{position:relative;flex:0 0 auto;padding:11px;border-radius:9px;background:var(--accent-light);border:1px solid var(--accent);display:flex;justify-content:space-between;gap:8px}.track article button{border:0;background:none;color:var(--error);font-size:18px}.track em{color:var(--text-muted);font-size:12px}@media(max-width:1000px){.editor-grid{grid-template-columns:1fr}.preview{height:240px}}</style>
